def search_until_ready(
    client: MemoryClient,
    *,
    user_id: str,
    agent_id: str,
    app_id: str,
    run_id: str,
) -> list[dict[str, Any]]:
    filters = build_filters(user_id, agent_id, app_id, run_id)
